oxy_webhelp_navlinks = {"tocId-d39536e9974":{"topics":[{"title":"Cluster retirement with archived data","shortdesc":"<p class=\"shortdesc\">When you decommission a Rubrik cluster that owns archival locations, you must transfer ownership of those locations to a replacement cluster to preserve access to archived data.<\/p>","href":"archival\/arch_retiring_cluster_with_archived_data.html","attributes":{"data-id":"arch_retiring_cluster_with_archived_data"},"menu":{"hasChildren":false},"tocID":"arch_retiring_cluster_with_archived_data-d39536e9975","topics":[]},{"title":"Moving archives between Rubrik clusters","shortdesc":"<p class=\"shortdesc\">Transfer archival location ownership between Rubrik clusters using the         Promote to Owner operation, without moving or copying any archived data.<\/p>","href":"archival\/arch_moving_archives_between_clusters.html","attributes":{"data-id":"arch_moving_archives_between_clusters"},"menu":{"hasChildren":false},"tocID":"arch_moving_archives_between_clusters-d39536e9986","topics":[]}]}};